package com.packetanalyzer.firewall;
import com.packetanalyzer.dpi.Application; import java.io.*; import java.util.*; import java.util.concurrent.*;
public final class RuleManager {private final Set<String> ips=ConcurrentHashMap.newKeySet(),domains=ConcurrentHashMap.newKeySet();private final Set<Integer> ports=ConcurrentHashMap.newKeySet();private final Set<Application> apps=ConcurrentHashMap.newKeySet(); public void blockIp(String x){ips.add(x);} public void blockDomain(String x){domains.add(x.toLowerCase());} public void blockPort(int x){ports.add(x);} public void blockApp(Application x){apps.add(x);} public boolean blocked(String ip,int port,Application app,String domain){return blocked(ip,ip,port,port,app,domain);}
 public boolean blocked(String srcIp,String dstIp,int srcPort,int dstPort,Application app,String domain){String d=domain==null?"":domain.toLowerCase();return ips.contains(srcIp)||ips.contains(dstIp)||ports.contains(srcPort)||ports.contains(dstPort)||apps.contains(app)||domains.stream().anyMatch(x->x.equals(d)||(x.startsWith("*.")&&d.endsWith(x.substring(1))));} public void load(String f)throws IOException{try(BufferedReader r=new BufferedReader(new FileReader(f))){for(String line;(line=r.readLine())!=null;){line=line.trim();if(line.isEmpty()||line.startsWith("#"))continue;String[]a=line.split("=",2);if(a.length!=2)continue;switch(a[0].trim().toUpperCase()){case"BLOCK_IP"->blockIp(a[1].trim());case"BLOCK_PORT"->blockPort(Integer.parseInt(a[1].trim()));case"BLOCK_DOMAIN"->blockDomain(a[1].trim());case"BLOCK_APP"->blockApp(Application.valueOf(a[1].trim().toUpperCase()));}}}} public String summary(){return "IPs="+ips.size()+", ports="+ports.size()+", domains="+domains.size()+", apps="+apps.size();}}
